examples.input:
[fid, msg] = fopen('log.txt', 'r');
assert(fid ~= -1, msg);
while ~feof(fid)
    line = fgets(fid);
    disp(line);
end
fclose(fid)

[fid, msg] = fopen('payload.bin', 'rb');
assert(fid ~= -1, msg);
while ~feof(fid)
    chunk = fread(fid, 1024, 'uint8');
    process(chunk);
end
fclose(fid)

[fid, msg] = fopen('empty.txt', 'r');
assert(fid ~= -1, msg);
assert(~feof(fid));
fgets(fid);            % encounters end-of-file
assert(feof(fid));
frewind(fid);
assert(~feof(fid));
fclose(fid)

try
    feof(9999);
catch err
    disp(err.message);
end
